      </div>
      <div class="chart-card">
        <h3>Yearly Price-Rating Correlation</h3>
        <div class="chart-wrap"><canvas id="yearlyCorrChart"></canvas></div>
      </div>
    </div>

    <div class="chart-card">
      <h3>Inflection Point Timeline</h3>
      <table class="comp-table">
        <thead>
          <tr><th>Year</th><th>Event</th><th>Avg Price</th><th>Avg Rating</th><th>Avg Reviews</th><th>Fiction %</th></tr>
        </thead>
        <tbody>
